(function () {
  // ── shared helpers (SVG, tweening) ─────────────────────────────────────────
  var NS = "http://www.w3.org/2000/svg";
  var svg = document.getElementById("scene");
  var labelEl = document.getElementById("step-label");
  var captionEl = document.getElementById("caption");

  function el(name, attrs, parent) {
    var node = document.createElementNS(NS, name);
    for (var key in attrs) node.setAttribute(key, attrs[key]);
    if (parent) parent.appendChild(node);
    return node;
  }
  function txt(parent, x, y, cls, str, anchor) {
    var t = el("text", { x: x, y: y, class: cls }, parent);
    if (anchor) t.setAttribute("text-anchor", anchor);
    t.textContent = str;
    return t;
  }
  function show(node, on) {
    node.setAttribute("opacity", on ? "1" : "0");
  }
  function place(node, x, y) {
    node.style.transform = "translate(" + x + "px," + y + "px)";
  }
  function setLine(node, x1, y1, x2, y2) {
    node.setAttribute("x1", x1);
    node.setAttribute("y1", y1);
    node.setAttribute("x2", x2);
    node.setAttribute("y2", y2);
  }
  function lerp(a, b, e) {
    return a + (b - a) * e;
  }
  function round1(v) {
    return (Math.round(v * 10) / 10).toFixed(1);
  }

  // Eased animation. fn(e) is called with e from 0 to 1. Without
  // requestAnimationFrame (or with ms = 0) it jumps straight to fn(1).
  var animTokens = {};
  function anim(key, ms, fn) {
    var token = (animTokens[key] || 0) + 1;
    animTokens[key] = token;
    if (typeof requestAnimationFrame !== "function" || ms <= 0) {
      fn(1);
      return;
    }
    var start = null;
    function frame(now) {
      if (animTokens[key] !== token) return;
      if (start === null) start = now;
      var p = Math.min(1, (now - start) / ms);
      var e = p < 0.5 ? 2 * p * p : 1 - Math.pow(-2 * p + 2, 2) / 2;
      fn(e);
      if (p < 1) requestAnimationFrame(frame);
    }
    requestAnimationFrame(frame);
  }

  // Arrowheads, one marker per colour.
  var COLORS = { g: "#1DB584", y: "#E2B44A", p: "#F472B6", b: "#38BDF8", w: "#c9dccf", r: "#F87171" };
  var defs = el("defs", {}, svg);
  Object.keys(COLORS).forEach(function (k) {
    var m = el("marker", { id: "ah-" + k, viewBox: "0 0 10 10", refX: 9, refY: 5, markerUnits: "userSpaceOnUse", markerWidth: 13, markerHeight: 13, orient: "auto" }, defs);
    el("path", { d: "M0 0 L10 5 L0 10 Z", fill: COLORS[k] }, m);
  });
  function arrow(parent, colorKey, width) {
    return el("line", { x1: 0, y1: 0, x2: 0, y2: 0, stroke: COLORS[colorKey], "stroke-width": width || 3, "marker-end": "url(#ah-" + colorKey + ")", "stroke-linecap": "round" }, parent);
  }
  function polygon(parent, cls) {
    return el("polygon", { points: "", class: cls }, parent);
  }
  function setPoly(node, pts) {
    node.setAttribute("points", pts.map(function (p) { return p[0].toFixed(1) + "," + p[1].toFixed(1); }).join(" "));
  }
  function lerpPts(a, b, e) {
    return a.map(function (p, i) { return [lerp(p[0], b[i][0], e), lerp(p[1], b[i][1], e)]; });
  }
  // Maps maths coordinates (x right, y up) to screen pixels.
  function makePlane(cx, cy, s) {
    return {
      x: function (v) { return cx + s * v; },
      y: function (v) { return cy - s * v; },
      pt: function (p) { return [cx + s * p[0], cy - s * p[1]]; },
      s: s, cx: cx, cy: cy
    };
  }
  function axes(parent, plane, xr, yr) {
    el("line", { x1: plane.x(-xr), y1: plane.y(0), x2: plane.x(xr), y2: plane.y(0), class: "axis" }, parent);
    el("line", { x1: plane.x(0), y1: plane.y(-yr), x2: plane.x(0), y2: plane.y(yr), class: "axis" }, parent);
  }

  var EXPLAIN = {"target-vector":{"h":"WHAT YOU ARE LOOKING AT","t":"Here is a vector **a**. Suppose we are only allowed to **move along one direction**."},"direction":{"h":"A DIRECTION b","t":"That direction is the **line through the vector b**. Which point on this line is **closest to a**?"},"drop-perpendicular":{"h":"DROP A PERPENDICULAR","t":"Drop a straight line from the tip of a down to the line, meeting it at a **right angle**. The shortest route is always perpendicular."},"projection":{"h":"THE PROJECTION IS THE SHADOW","t":"Where the perpendicular lands is the **projection** of a onto b: the part of a that points **along b**."},"residual":{"h":"WHAT IS LEFT OVER: THE RESIDUAL","t":"The leftover part, **a minus its projection**, is the **residual**. It is **perpendicular to b**."},"formula":{"h":"THE FORMULA BEHIND THE PICTURE","t":"The shadow's length comes from the dot product: **proj = ((a · b) / (b · b)) · b**."},"ml-connection":{"h":"TAKEAWAY","t":"The projection is the **closest point to a using only direction b**. Least squares and PCA are built on this idea."}};
  // ── scene ──
  var steps = [
    { id: "target-vector", label: "A vector a we want to describe", caption: "Here is a vector a. Suppose we are only allowed to move along one direction." },
    { id: "direction", label: "A direction b", caption: "That direction is the line through the vector b. Which point on this line is closest to a?" },
    { id: "drop-perpendicular", label: "Drop a perpendicular", caption: "Drop a straight line from the tip of a down to the line, meeting it at a right angle." },
    { id: "projection", label: "The projection is the shadow", caption: "Where the perpendicular lands is the projection of a onto b: the part of a that points along b." },
    { id: "residual", label: "What is left over: the residual", caption: "The leftover part, a minus its projection, is the residual. It is perpendicular to b." },
    { id: "formula", label: "The formula behind the picture", caption: "The shadow's length comes from the dot product: proj = ((a · b) / (b · b)) · b." },
    { id: "ml-connection", label: "The best approximation along a direction", caption: "The projection is the closest point to a using only direction b. Least squares and PCA are built on this idea." }
  ];

  var P = makePlane(80, 318, 62);
  var A = [4, 3];
  var B = [5, 2];
  var dotAB = A[0] * B[0] + A[1] * B[1];
  var dotBB = B[0] * B[0] + B[1] * B[1];
  var k = dotAB / dotBB;
  var PR = [k * B[0], k * B[1]];
  var RES = [A[0] - PR[0], A[1] - PR[1]];

  el("line", { x1: P.x(0), y1: P.y(0), x2: P.x(0), y2: P.y(4.9), class: "axis" }, svg);
  el("line", { x1: P.x(-0.4), y1: P.y(0), x2: P.x(9), y2: P.y(0), class: "axis" }, svg);

  var dirLine = el("line", { x1: P.x(-1), y1: P.y(-0.4), x2: P.x(7.3), y2: P.y(2.92), stroke: "#38bdf8", "stroke-width": 1.5, class: "dash" }, svg);
  var arrB = arrow(svg, "b", 4);
  setLine(arrB, P.x(0), P.y(0), P.x(B[0]), P.y(B[1]));
  var labB = txt(svg, P.x(B[0]) + 8, P.y(B[1]) + 4, "lbl lbl-b", "b");

  var arrA = arrow(svg, "g", 4);
  setLine(arrA, P.x(0), P.y(0), P.x(A[0]), P.y(A[1]));
  var labA = txt(svg, P.x(A[0]) - 6, P.y(A[1]) - 10, "lbl lbl-g", "a");

  var drop = el("line", { class: "dash", stroke: "#f472b6", "stroke-width": 2 }, svg);
  setLine(drop, P.x(A[0]), P.y(A[1]), P.x(PR[0]), P.y(PR[1]));

  // Right-angle mark where the perpendicular meets the line.
  var ub = [B[0] / Math.sqrt(dotBB), B[1] / Math.sqrt(dotBB)];
  var rl = Math.sqrt(RES[0] * RES[0] + RES[1] * RES[1]);
  var un = [RES[0] / rl, RES[1] / rl];
  var sq = 0.3;
  var rightMark = el("polyline", { fill: "none", stroke: "#e2b44a", "stroke-width": 2 }, svg);
  rightMark.setAttribute("points", [
    [PR[0] - sq * ub[0], PR[1] - sq * ub[1]],
    [PR[0] - sq * ub[0] + sq * un[0], PR[1] - sq * ub[1] + sq * un[1]],
    [PR[0] + sq * un[0], PR[1] + sq * un[1]]
  ].map(function (p) { return P.x(p[0]) + "," + P.y(p[1]); }).join(" "));

  var arrProj = arrow(svg, "y", 5);
  setLine(arrProj, P.x(0), P.y(0), P.x(PR[0]), P.y(PR[1]));
  var labProj = txt(svg, P.x(PR[0]) + 12, P.y(PR[1]) + 20, "lbl lbl-y", "projection");

  var arrRes = arrow(svg, "p", 4);
  setLine(arrRes, P.x(PR[0]), P.y(PR[1]), P.x(A[0]), P.y(A[1]));
  var labRes = txt(svg, P.x(A[0]) + 30, P.y(A[1]) + 40, "lbl lbl-p", "residual ⟂ b");

  var panel = el("g", {}, svg);
  el("rect", { x: 392, y: 246, width: 240, height: 106, rx: 12, fill: "#071510" }, panel); // opaque base so the axis does not show through the text
  el("rect", { x: 392, y: 246, width: 240, height: 106, rx: 12, class: "fillG" }, panel);
  txt(panel, 406, 268, "mono", "proj = ((a · b) / (b · b)) b", "start");
  txt(panel, 406, 292, "note", "a · b = 4·5 + 3·2 = " + dotAB, "start");
  txt(panel, 406, 310, "note", "b · b = 5·5 + 2·2 = " + dotBB, "start");
  txt(panel, 406, 336, "mono", "proj ≈ " + (Math.round(k * 100) / 100) + " · b", "start");
  var mlPanel = el("g", {}, svg);
  el("rect", { x: 392, y: 250, width: 240, height: 90, rx: 12, fill: "#071510" }, mlPanel);
  el("rect", { x: 392, y: 250, width: 240, height: 90, rx: 12, class: "fillG" }, mlPanel);
  txt(mlPanel, 406, 276, "lbl", "closest point to a", "start");
  txt(mlPanel, 406, 296, "lbl", "along the direction b", "start");
  txt(mlPanel, 406, 322, "note", "→ least squares, PCA", "start");

  function render(index, id) {
    show(arrA, true); show(labA, true);
    show(dirLine, index >= 1); show(arrB, index >= 1); show(labB, index >= 1);
    show(drop, index >= 2); show(rightMark, index >= 2);
    show(arrProj, index >= 3); show(labProj, index >= 3);
    show(arrRes, index >= 4); show(labRes, index >= 4);
    show(panel, id === "formula");
    show(mlPanel, id === "ml-connection");
  }


  // ── shared runtime: stepping, explanation panel, educational autoplay pacing, bridge ──
  var current = 0;
  var explainHeadEl = document.getElementById("explain-h");

  // **bold** markers in an explanation become <strong> nodes (built with DOM calls, never innerHTML).
  function setRich(node, str) {
    node.textContent = "";
    var parts = String(str).split("**");
    for (var i = 0; i < parts.length; i++) {
      if (parts[i] === "") continue;
      var seg = document.createElement(i % 2 ? "strong" : "span");
      seg.textContent = parts[i];
      node.appendChild(seg);
    }
  }

  function explanationFor(index) {
    var ex = (typeof EXPLAIN === "object" && EXPLAIN) ? EXPLAIN[steps[index].id] : null;
    return ex || { h: "WHAT IS HAPPENING", t: steps[index].caption };
  }

  // Autoplay pace: 4.5 to 10.5 seconds per step, longer for longer explanations, so a learner can read.
  function stepMs(index) {
    var words = String(explanationFor(index).t).replace(/\*\*/g, "").split(/\s+/).length;
    return Math.max(4500, Math.min(10500, Math.round(3800 + words * 165)));
  }

  function renderStep(index) {
    var ex = explanationFor(index);
    labelEl.textContent = steps[index].label;
    if (explainHeadEl) explainHeadEl.textContent = ex.h;
    setRich(captionEl, ex.t);
    render(index, steps[index].id);
  }

  function goTo(index) {
    if (index < 0 || index >= steps.length) return;
    current = index;
    renderStep(current);
    if (window.ReagvisBridge) window.ReagvisBridge.stepChanged(steps[current].id);
  }

  renderStep(current);

  // Autoplay: exactly one timer, one step per tick, stops on the final step.
  // PLAY on the final step restarts from the first step and plays again.
  var timer = null;

  function stopAuto() {
    if (timer !== null) {
      clearTimeout(timer);
      timer = null;
    }
  }

  function scheduleNext() {
    timer = setTimeout(function () {
      timer = null;
      if (current >= steps.length - 1) return;
      goTo(current + 1);
      if (current < steps.length - 1) scheduleNext();
    }, stepMs(current));
  }

  function startAuto() {
    if (timer !== null) return;
    if (current >= steps.length - 1) goTo(0);
    scheduleNext();
  }

  window.addEventListener("pagehide", stopAuto);

  window.ReagvisAnimation = {
    stepDuration: stepMs,
    onCommand: function (type, stepId) {
      if (type === "PLAY") startAuto();
      else if (type === "PAUSE") stopAuto();
      else if (type === "NEXT") { stopAuto(); goTo(current + 1); }
      else if (type === "PREVIOUS") { stopAuto(); goTo(current - 1); }
      else if (type === "RESET") { stopAuto(); goTo(0); }
      else if (type === "GOTO_STEP") {
        stopAuto();
        for (var i = 0; i < steps.length; i++) {
          if (steps[i].id === stepId) { goTo(i); break; }
        }
      }
    },
  };

  if (window.ReagvisBridge) {
    window.ReagvisBridge.ready();
    window.ReagvisBridge.stepChanged(steps[current].id);
  }
})();

